/**
 * Stylesheet for the {@link ReloadButton} top-left control. Sized 40×40 with
 * a 30px glyph to match the layer control and MapML-MapLibre's reload button.
 * Stacked directly below the native zoom control (two 40px buttons = 80px, +
 * an 8px gap), mirroring MapML.js's top-left order zoom → reload → fullscreen.
 */
export const reloadButtonCss = /* css */ `
.mapml-reload-button {
  left: .5em;
  padding: 0;
  background-color: #fff;
  border: 1px solid #e3e3e3;
  border-radius: 4px;
  box-shadow: rgb(0 0 0 / 30%) 0px 1px 4px -1px;
}

.mapml-reload-button button.mapml-button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  /* Cancel ol.css's .ol-control button margin (1px) so the container stays
     40px wide, aligned with the zoom bar above it. */
  margin: 0;
  padding: 0;
  color: #333;
  background-color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

.mapml-reload-button .mapml-reload-button-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  font-size: 30px;
  font-weight: 700;
  line-height: 1;
}

.mapml-reload-button button.mapml-button[aria-disabled='true'],
.mapml-reload-button button.mapml-button:disabled {
  color: #bbb;
  cursor: default;
}

/* Drop ol.css's gray hover/focus outline and draw the shared focus ring. */
.mapml-reload-button > button:hover,
.mapml-reload-button > button:focus:not(:focus-visible) {
  outline: none;
}
.mapml-reload-button > button:focus-visible {
  outline: 2px solid var(--mapml-focus-ring-color);
  outline-offset: 1px;
}
`;
