/**
 * `<map-select>` — a declarative variable (like `<map-input>`) whose value is
 * chosen from `<map-option>` children, referenced by a sibling `<map-link>`'s
 * `tref` (e.g. a WMS `STYLES={style}`). Named `HTMLSelectElement` to match
 * MapML.js (module-scoped, deliberately shadowing the built-in interface).
 *
 * Ported from MapML.js `src/map-select.js`: on connect it transcribes its
 * `<map-option>` children into a real (detached) `<select>` exposed as
 * `htmlselect`, which `map-link` reads to substitute the current value. The
 * interactive layer-control rendering + redraw-on-change is Phase 11 scope.
 */
export class HTMLSelectElement extends HTMLElement {
  static get observedAttributes() {
    return ['name', 'id'];
  }

  get name() {
    return this.getAttribute('name');
  }
  set name(val) {
    this.setAttribute('name', val);
  }
  get id() {
    return this.getAttribute('id');
  }
  set id(val) {
    this.setAttribute('id', val);
  }

  get value() {
    return this.htmlselect?.value;
  }

  connectedCallback() {
    this.htmlselect = this.transcribe();
  }

  disconnectedCallback() {}

  // Build a real <select> mirroring this element's attributes + <map-option>
  // children (textContent, not innerHTML, so an option body cannot inject
  // markup). Ported 1:1 from MapML.js map-select.js `transcribe`.
  transcribe() {
    const select = document.createElement('select');
    const elementAttrNames = this.getAttributeNames();
    for (let i = 0; i < elementAttrNames.length; i++) {
      select.setAttribute(
        elementAttrNames[i],
        this.getAttribute(elementAttrNames[i])
      );
    }

    const options = this.children;
    for (let i = 0; i < options.length; i++) {
      const option = document.createElement('option');
      const optionAttrNames = options[i].getAttributeNames();
      for (let j = 0; j < optionAttrNames.length; j++) {
        option.setAttribute(
          optionAttrNames[j],
          options[i].getAttribute(optionAttrNames[j])
        );
      }
      option.textContent = options[i].textContent;
      select.appendChild(option);
    }
    return select;
  }

  whenReady() {
    return new Promise((resolve, reject) => {
      if (this.htmlselect) {
        resolve();
        return;
      }
      let interval, failureTimer;
      const testForSelect = () => {
        if (this.htmlselect) {
          clearInterval(interval);
          clearTimeout(failureTimer);
          resolve();
        } else if (!this.isConnected) {
          clearInterval(interval);
          clearTimeout(failureTimer);
          reject('Element disconnected');
        }
      };
      interval = setInterval(testForSelect, 300);
      failureTimer = setTimeout(() => {
        clearInterval(interval);
        reject('Timeout reached waiting for map-select to be ready');
      }, 10000);
    });
  }
}
