/*
 * OpenLayers CRS bridge — turns the framework-neutral `M[projection]` tables
 * (see GlobalM.js) into native `ol/proj` projections and `ol/tilegrid`
 * tile grids.
 *
 * This is the OL-native half of the hybrid: MapML's own `crs.*` data tables
 * and projection math stay in GlobalM.js / the Proj.CRS adapter, while the
 * map itself renders through these OL objects derived from the same numbers.
 *
 * The proj4 defs are registered by the Proj.CRS constructor when GlobalM.js
 * builds `M.WGS84`/`M.CBMTILE`/`M.APSTILE`/`M.OSMTILE`; `register(proj4)`
 * here bridges those defs (and their pairwise transforms) into `ol/proj`.
 * Built-in EPSG:3857 / EPSG:4326 are left intact — `register` only creates
 * projections for codes not already cached.
 */

import proj4 from 'proj4';
import { register } from 'ol/proj/proj4.js';
import { get as getOLProjection, addProjection } from 'ol/proj.js';
import Projection from 'ol/proj/Projection.js';
import TileGrid from 'ol/tilegrid/TileGrid.js';

const TILE_SIZE = 256;

let _registered = false;
const _projections = {};
const _tileGrids = {};

// Projected validity extent [minX, minY, maxX, maxY] from the M bounds table.
function extentOf(mProj) {
  const b = mProj.options.bounds;
  return [b.min.x, b.min.y, b.max.x, b.max.y];
}

// World extent in longitude/latitude from the gcrs table.
function worldExtentOf(mProj) {
  const g = mProj.options.crs.gcrs;
  return [g.horizontal.min, g.vertical.min, g.horizontal.max, g.vertical.max];
}

// @function registerProj4(): void
// Bridge the proj4 defs (registered by GlobalM's Proj.CRS ctor) into ol/proj.
export function registerProj4() {
  if (_registered) {
    return;
  }
  register(proj4);
  _registered = true;
}

// @function getProjection(mProj: Proj.CRS): ol/proj/Projection
// Returns the native OL projection for an `M[projection]`, augmenting it with
// the MapML extent/worldExtent so OL clamps and reprojects correctly.
export function getProjection(mProj) {
  const code = mProj.code;
  if (_projections[code]) {
    return _projections[code];
  }
  registerProj4();

  let projection = getOLProjection(code);
  if (!projection) {
    projection = new Projection({
      code,
      units: code === 'EPSG:4326' ? 'degrees' : 'm',
      extent: extentOf(mProj)
    });
    addProjection(projection);
  }
  projection.setExtent(extentOf(mProj));
  projection.setWorldExtent(worldExtentOf(mProj));
  projection.setGlobal(code === 'EPSG:3857' || code === 'EPSG:4326');

  _projections[code] = projection;
  return projection;
}

// @function getTileGrid(mProj: Proj.CRS): ol/tilegrid/TileGrid
// Builds the tile grid from the same origin + resolutions the M tables use.
export function getTileGrid(mProj) {
  const code = mProj.code;
  if (_tileGrids[code]) {
    return _tileGrids[code];
  }
  const tileGrid = new TileGrid({
    extent: extentOf(mProj),
    origin: mProj.options.origin,
    resolutions: mProj.options.resolutions,
    tileSize: TILE_SIZE
  });
  _tileGrids[code] = tileGrid;
  return tileGrid;
}
