/**
 * `<map-feature>` — a single vector feature. Ported from MapML.js
 * `src/map-feature.js` (the custom-element surface: `zoom`/`min`/`max`/`extent`
 * getters, lifecycle, native-zoom bounds). Rendering is re-architected: instead
 * of a Leaflet SVG `Geometry`, a `<map-feature>` contributes one `ol/Feature`
 * to a `MapFeatureLayer` (an `ol/layer/Vector`).
 *
 * A feature renders into its `<map-layer>`'s feature layer when authored inline,
 * or into a `<map-link rel=features>`'s templated feature layer when grafted
 * into that link's shadow root (the MAP-LINK branch of `connectedCallback`).
 * Attribute changes (`zoom`/`min`/`max`) re-render via `attributeChangedCallback`;
 * the full subtree MutationObserver re-render is still deferred. Hover tooltip +
 * click popup interactivity is handled at the map level by `FeatureInteraction`.
 */
import { Util } from './mapml/utils/Util.js';
import { toPoint as point } from './mapml/geometry/Point.js';
import { toBounds as bounds } from './mapml/geometry/Bounds.js';

export class HTMLFeatureElement extends HTMLElement {
  static get observedAttributes() {
    return ['zoom', 'min', 'max'];
  }

  // Native zoom the feature's coordinates are authored at. For static features:
  // the `zoom` attribute, else the map's zoom when the feature connected.
  get zoom() {
    return +(this.hasAttribute('zoom')
      ? this.getAttribute('zoom')
      : this._initialZoom);
  }
  set zoom(val) {
    var parsedVal = parseInt(val, 10);
    if (!isNaN(parsedVal) && parsedVal >= this.min && parsedVal <= this.max) {
      this.setAttribute('zoom', parsedVal);
    }
  }

  get min() {
    let meta = {},
      metaEl = this.getMeta('zoom');
    if (metaEl) meta = Util._metaContentToObject(metaEl.getAttribute('content'));
    let projectionMinZoom = 0;
    // min attribute || map-meta zoom min || projection minZoom
    return +(this.hasAttribute('min')
      ? this.getAttribute('min')
      : meta.min
      ? meta.min
      : projectionMinZoom);
  }

  get max() {
    let meta = {},
      metaEl = this.getMeta('zoom');
    if (metaEl) meta = Util._metaContentToObject(metaEl.getAttribute('content'));
    const projection = this.getLayerEl().getProjection();
    let projectionMaxZoom =
      window.M[projection].options.resolutions.length - 1;
    // max attribute || map-meta zoom max || projection maxZoom
    return +(this.hasAttribute('max')
      ? this.getAttribute('max')
      : meta.max
      ? meta.max
      : projectionMaxZoom);
  }

  get extent() {
    if (!this.isConnected) {
      return undefined;
    }
    if (!this._getFeatureExtent) {
      this._getFeatureExtent = this._memoizeExtent();
    }
    return this._getFeatureExtent();
  }

  getMapEl() {
    return Util.getClosest(this, 'mapml-viewer,map[is=web-map]');
  }
  getLayerEl() {
    return Util.getClosest(this, 'map-layer,layer-');
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (this._hasConnected) {
      switch (name) {
        case 'min':
        case 'max':
        case 'zoom':
          if (oldValue !== newValue) {
            this.reRender(this._featureLayer);
          }
          break;
      }
    }
  }

  constructor() {
    super();
  }

  async connectedCallback() {
    this._hasConnected = true;
    // Resolve the owning element: a light-DOM <map-layer>, or — when this
    // feature was grafted into a <map-link rel=features> shadow root — the
    // shadow host (the <map-link>). Ported from MapML.js map-feature.js.
    this._parentEl =
      this.parentNode.nodeName === 'MAP-LAYER' ||
      this.parentNode.nodeName === 'MAP-LINK'
        ? this.parentNode
        : this.parentNode.host;
    if (
      this._parentEl?.nodeName !== 'MAP-LAYER' &&
      this._parentEl?.nodeName !== 'MAP-LINK'
    ) {
      return;
    }
    this._viewer = this.getMapEl();
    // initial zoom is the fallback native zoom for features without a zoom attr
    this._initialZoom = this._viewer?.zoom ?? 0;
    await this._viewer.whenReady();
    if (!this.isConnected) {
      return;
    }
    if (this._parentEl.nodeName === 'MAP-LINK') {
      // Templated feature: render into the link's templated feature layer
      // (owned by its TemplatedFeaturesOrTilesLayer controller). Ported from
      // MapML.js map-feature.js `_createOrGetFeatureLayer` MAP-LINK branch.
      // TODO (Phase 11, <map-tile>): MapML.js selects the layer from a
      // per-position `_layerRegistry` so interleaved tile/feature runs keep
      // DOM z-order; here it's a single features layer (see the controller doc).
      const featureLayer = this._parentEl._getTemplatedFeatureLayer();
      if (featureLayer) {
        this.addFeature(featureLayer);
      }
    } else {
      // ensure the layer's ol/Group exists, then attach to its feature layer
      this._parentEl.getLayerGroup();
      const featureLayer = this._parentEl._getFeatureLayer();
      this.addFeature(featureLayer);
    }
  }

  disconnectedCallback() {
    if (this._featureLayer && this._olFeature) {
      this.removeFeature(this._featureLayer);
    }
  }

  reRender(layerToRenderOn) {
    if (!layerToRenderOn || !this.isConnected) return;
    if (this._olFeature) {
      layerToRenderOn.removeLayer(this._olFeature);
    }
    delete this._getFeatureExtent;
    this.addFeature(layerToRenderOn);
  }

  addFeature(layerToAddTo) {
    this._featureLayer = layerToAddTo;
    if (!this.querySelector('map-geometry')) return;
    const fallbackCS = this._getFallbackCS();
    this._olFeature = layerToAddTo.createGeometry(this, fallbackCS);
    if (!this._olFeature) return;
    layerToAddTo.addLayer(this._olFeature);
  }

  removeFeature(layerToRemoveFrom) {
    layerToRemoveFrom.removeLayer(this._olFeature);
    this._olFeature = null;
    if (this._getFeatureExtent) delete this._getFeatureExtent;
  }

  // Simulate a user click: dispatch a cancelable `click` on this element (so
  // `addEventListener('click')` handlers run) and, unless suppressed, toggle
  // this feature's properties popup. Ported from MapML.js `map-feature.click`,
  // re-routed through the map-level FeatureInteraction handler since OL has no
  // per-feature DOM to click.
  click() {
    const clickEv = new PointerEvent('click', { cancelable: true });
    this.dispatchEvent(clickEv);
    const featureInteraction = this._viewer?._featureInteraction;
    if (
      !this.querySelector('map-properties') ||
      !this.isConnected ||
      clickEv.defaultPrevented ||
      !featureInteraction
    ) {
      return;
    }
    if (featureInteraction.isPopupOpenFor(this)) {
      featureInteraction.closePopup();
    } else {
      featureInteraction.openPopup(this);
    }
  }

  // Move keyboard focus to this feature (the OL analog of MapML.js focusing the
  // SVG <g>): focus this feature's FeatureIndex proxy, which reveals the focus
  // ring. Ported from MapML.js map-feature.js `focus`. No-op if the feature is
  // not currently indexed (out of view / zoom range).
  focus(options) {
    this._viewer?._featureIndex?.focusFeature(this, options);
  }

  // Blur this feature and return focus to the map, but only while the feature
  // holds focus. Ported from MapML.js map-feature.js `blur`.
  blur() {
    this._viewer?._featureIndex?.blurFeature(this);
  }

  // Centre the viewport on this feature's extent. Ported from MapML.js
  // `map-feature.zoomTo`; OL's `view.fit` supplies the "show the whole feature"
  // behaviour of MapML.js's `getZoomToZoom`/`Util.getMaxZoom`.
  zoomTo() {
    const geometry = this._olFeature?.getGeometry();
    const view = this._viewer?.map?.getView();
    if (!geometry || !view) return;
    const extent = geometry.getExtent();
    if (this.hasAttribute('zoom')) {
      view.setCenter([
        (extent[0] + extent[2]) / 2,
        (extent[1] + extent[3]) / 2
      ]);
      view.setZoom(this.zoom);
    } else {
      view.fit(extent, { maxZoom: this.max });
    }
  }

  // native cs: the fallback cs for <map-geometry> when its cs attribute is
  // absent. Static path: the layer's map-meta[name=cs]; templated path: the
  // response cs meta in the link's shadow root, else the extent's. Else 'gcrs'.
  // Ported from MapML.js map-feature.js `_getFallbackCS`.
  _getFallbackCS() {
    let csMeta;
    if (this._parentEl?.nodeName === 'MAP-LINK') {
      csMeta =
        this._parentEl.shadowRoot?.querySelector(
          'map-meta[name=cs][content]'
        ) || this._parentEl._extent?.getMeta('cs');
    } else {
      const layerEl = this.getLayerEl();
      csMeta = layerEl?.src
        ? layerEl.shadowRoot?.querySelector('map-meta[name=cs][content]')
        : layerEl?.querySelector('map-meta[name=cs][content]');
    }
    return csMeta
      ? Util._metaContentToObject(csMeta.getAttribute('content')).content
      : 'gcrs';
  }

  _getZoomBounds() {
    // ** native zoom is only used for zoomTo() **
    return {
      minZoom: this.min,
      maxZoom: this.max,
      minNativeZoom: this.zoom,
      maxNativeZoom: this.zoom
    };
  }

  getMeta(metaName) {
    let name = metaName.toLowerCase();
    if (name !== 'cs' && name !== 'zoom' && name !== 'projection') return;
    if (this._parentEl?.nodeName === 'MAP-LINK') {
      // Templated feature: link shadow-root meta, else the extent's. Ported
      // from MapML.js map-feature.js getMeta MAP-LINK branch.
      return (
        this._parentEl.shadowRoot?.querySelector(
          `map-meta[name=${name}][content]`
        ) || this._parentEl._extent?.getMeta(name)
      );
    }
    const layerEl = this.getLayerEl();
    return layerEl?.src
      ? layerEl.shadowRoot?.querySelector(`map-meta[name=${name}][content]`)
      : layerEl?.querySelector(`:scope > map-meta[name=${name}][content]`);
  }

  // Compute + memoize the feature's extent (PCRS bounds -> {gcrs,pcrs,tcrs,
  // tilematrix, zoom}). Ported from MapML.js `_memoizeExtent`.
  _memoizeExtent() {
    let extentCache;
    return function () {
      if (extentCache && this._getFeatureExtent) {
        return extentCache;
      }
      let projection = this.getLayerEl().getProjection(),
        crs = window.M[projection],
        geometry = this.querySelector('map-geometry'),
        cs = geometry.getAttribute('cs') || this._getFallbackCS(),
        zoom = this.zoom,
        shapes = geometry.querySelectorAll(
          'map-point, map-linestring, map-polygon, map-multipoint, map-multilinestring'
        ),
        bboxExtent = [
          Infinity,
          Infinity,
          Number.NEGATIVE_INFINITY,
          Number.NEGATIVE_INFINITY
        ];
      for (let shape of shapes) {
        let coord = shape.querySelectorAll('map-coordinates');
        for (let i = 0; i < coord.length; ++i) {
          bboxExtent = _updateExtent(shape, coord[i], bboxExtent);
        }
      }
      let topLeft = point(bboxExtent[0], bboxExtent[1]);
      let bottomRight = point(bboxExtent[2], bboxExtent[3]);
      let pcrsBound = Util.boundsToPCRSBounds(
        bounds(topLeft, bottomRight),
        zoom,
        projection,
        cs
      );
      if (shapes.length === 1 && shapes[0].tagName.toUpperCase() === 'MAP-POINT') {
        let maxZoom = this.hasAttribute('max')
            ? +this.getAttribute('max')
            : crs.options.resolutions.length - 1,
          tileCenter = crs.options.crs.tile.bounds.getCenter(),
          pixel = crs.transformation.transform(
            pcrsBound.min,
            crs.scale(+this.zoom || maxZoom)
          );
        pcrsBound = Util.pixelToPCRSBounds(
          bounds(pixel.subtract(tileCenter), pixel.add(tileCenter)),
          this.zoom || maxZoom,
          projection
        );
      }
      let result = Object.assign(
        Util._convertAndFormatPCRS(pcrsBound, crs, projection),
        { zoom: this._getZoomBounds() }
      );
      extentCache = result;
      return result;
    };

    function _updateExtent(shape, coord, bboxExtent) {
      let data = coord.innerHTML
        .trim()
        .replace(/<[^>]+>/g, '')
        .replace(/\s+/g, ' ')
        .split(/[<> ]/g);
      switch (shape.tagName.toUpperCase()) {
        case 'MAP-POINT':
          bboxExtent = Util._updateExtent(bboxExtent, +data[0], +data[1]);
          break;
        case 'MAP-LINESTRING':
        case 'MAP-POLYGON':
        case 'MAP-MULTIPOINT':
        case 'MAP-MULTILINESTRING':
          for (let i = 0; i < data.length; i += 2) {
            bboxExtent = Util._updateExtent(bboxExtent, +data[i], +data[i + 1]);
          }
          break;
        default:
          break;
      }
      return bboxExtent;
    }
  }
}
