import Attribution from 'ol/control/Attribution.js';

/**
 * MapML-flavoured attribution control.
 *
 * Extends OpenLayers' `ol/control/Attribution` to force a fixed W3C
 * Community Group prefix left-most in the attribution row (OL merges
 * source attributions into an unordered Set, so we override
 * `collectSourceAttributions_` — the same private hook MapML-MapLibre's
 * `MapmlAttributionControl` overrides — to prepend the prefix and keep
 * the remaining source attributions in insertion order).
 *
 * The collapsed/expanded toggle is a circular info-outline disclosure
 * button styled by `attributionControl.css.js`; the labels are emptied
 * so only the icon shows.
 *
 * The expanded row also carries a left-most "Keyboard shortcuts" button
 * (localized via `locale.kbdShortcuts`) that opens a `<dialog>` listing
 * the MapKeyboard shortcuts, and the control element gets a localized
 * `aria-label` (`locale.btnAttribution`) — both ported from MapML.js's
 * `AttributionButton`.
 *
 * The fixed content is ported from MapML-MapLibre's viewer
 * (`MAPS4HTML_ATTRIBUTION_HTML`) minus the MapLibre wordmark link, which
 * does not apply to the OpenLayers port.
 */

// W3C Community-and-Business-Groups icon (base64), mirrored from MapML.js's
// AttributionButton so this port carries the same badge.
const MAPS4HTML_W3CCG_ICON =
  'data:image/x-icon;base64,';

const MAPS4HTML_ATTRIBUTION_HTML =
  `<img src="${MAPS4HTML_W3CCG_ICON}" class="mapml-cg-logo" alt="W3C Community and Business Groups logo"> ` +
  `<a href="https://www.w3.org/community/maps4html/" target="_blank" rel="noopener">Maps for HTML Community Group</a>`;

// OpenLayers three-diamond brand mark (openlayers.org logo, base64 SVG), inlined
// so the attribution has no network dependency. Rendered inside the permanent
// openlayers.org link, to the right of the Maps4HTML entry.
const OPENLAYERS_LOGO_ICON =
  'data:image/svg+xml;base64,';

const OPENLAYERS_ATTRIBUTION_HTML =
  `<a href="https://openlayers.org/" target="_blank" rel="noopener" title="OpenLayers">` +
  `<img src="${OPENLAYERS_LOGO_ICON}" class="mapml-ol-logo" alt="">OpenLayers</a>`;

// Fixed, always-present attributions in display order (left-to-right).
const FIXED_ATTRIBUTIONS = [
  MAPS4HTML_ATTRIBUTION_HTML,
  OPENLAYERS_ATTRIBUTION_HTML
];

export class AttributionControl extends Attribution {
  constructor(options = {}) {
    const { viewer, ...rest } = options;
    super({
      collapsible: true,
      // Empty labels — the circular info-outline icon comes from CSS.
      label: '',
      collapseLabel: '',
      ...rest
    });
    // Viewer supplies the resolved locale (see mapml-viewer _setLocale).
    this._viewer = viewer;
  }

  _locale() {
    return this._viewer?.locale || window.M.options.locale;
  }

  // Left-most entry: a button that opens the keyboard-shortcuts dialog. The
  // inline onclick (mirrors MapML.js's AttributionButton) survives OL's
  // innerHTML re-renders, unlike an attached listener.
  _shortcutsButtonHtml() {
    const locale = this._locale();
    return (
      `<button type="button" class="shortcuts-button mapml-button" ` +
      `onclick="this.closest('.mapml-container')?.querySelector('.shortcuts-dialog')?.showModal()">` +
      `${locale.kbdShortcuts}</button>`
    );
  }

  // Force the shortcuts button, then the fixed prefixes (W3C CG, then
  // OpenLayers) left-most, then the source attributions in insertion order.
  // Overrides OL's private hook (mirrors MapML-MapLibre).
  collectSourceAttributions_(frameState) {
    const sources = super
      .collectSourceAttributions_(frameState)
      .filter((a) => !FIXED_ATTRIBUTIONS.includes(a));
    return [this._shortcutsButtonHtml(), ...FIXED_ATTRIBUTIONS, ...sources];
  }

  setMap(map) {
    super.setMap(map);
    if (map) {
      // role + aria-label mirror MapML.js's attribution container semantics.
      const label = this._locale().btnAttribution;
      this.element.setAttribute('role', 'group');
      this.element.setAttribute('aria-label', label);
      // OL's toggle tooltip/aria-label default to 'Attributions'; localize it.
      const button = this.element.querySelector('button');
      if (button) {
        button.title = label;
        button.setAttribute('aria-label', label);
      }
      this._ensureShortcutsDialog(map);
    } else {
      this._shortcutsDialog?.remove();
      this._shortcutsDialog = null;
    }
  }

  _ensureShortcutsDialog(map) {
    const target = map.getTargetElement();
    if (!target || this._shortcutsDialog?.isConnected) {
      return;
    }
    const locale = this._locale();
    const dialog = document.createElement('dialog');
    dialog.className = 'shortcuts-dialog';
    dialog.setAttribute('autofocus', '');
    dialog.addEventListener('click', (e) => {
      // Close on the ✕ button (same glyph as the layer control's remove
      // button); swallow clicks so they don't reach the map.
      if (e.target.closest('.shortcuts-close')) dialog.close();
      e.stopPropagation();
    });
    // The viewer's keyboard handling can preventDefault Escape (suppressing
    // the dialog's native cancel), so close explicitly here.
    dialog.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        e.stopPropagation();
        dialog.close();
      }
    });
    // Shortcuts listed reflect this port's MapKeyboard handler: arrow pan,
    // +/- whole-level zoom, Shift = 3×, Ctrl = 0.25× pan increment. (Feature
    // navigation is added when map-feature lands.)
    dialog.innerHTML =
      `<b>${locale.kbdShortcuts} </b>` +
      `<button type="button" aria-label="Close" class="shortcuts-close mapml-button"><span aria-hidden="true">&#10005;</span></button>` +
      `<ul><b>${locale.kbdMovement}</b>` +
      `<li><kbd>&#8593;</kbd> ${locale.kbdPanUp}</li>` +
      `<li><kbd>&#8595;</kbd> ${locale.kbdPanDown}</li>` +
      `<li><kbd>&#8592;</kbd> ${locale.kbdPanLeft}</li>` +
      `<li><kbd>&#8594;</kbd> ${locale.kbdPanRight}</li>` +
      `<li><kbd>+</kbd> ${locale.btnZoomIn}</li>` +
      `<li><kbd>-</kbd> ${locale.btnZoomOut}</li>` +
      `<li><kbd>shift</kbd> + <kbd>&#8592;/&#8593;/&#8594;/&#8595;</kbd> 3x ${locale.kbdPanIncrement}</li>` +
      `<li><kbd>ctrl</kbd> + <kbd>&#8592;/&#8593;/&#8594;/&#8595;</kbd> 0.25x ${locale.kbdPanIncrement}</li>` +
      `</ul>`;
    target.appendChild(dialog);
    this._shortcutsDialog = dialog;
  }
}
