// Ported from MapML.js's src/mapml/utils/DOMTokenList.js. A DOMTokenList shim
// backing the `controlslist` attribute on <mapml-viewer>: it wraps a donor
// <div>'s native classList (so parsing/iteration/de-dup come from the platform)
// and reflects every mutation back to the owner element's attribute. The
// `#valueSet` guard breaks the re-entrance loop between the setter and the
// custom element's attributeChangedCallback; `supports()` validates a token
// against the fixed domain the viewer understands.
export class DOMTokenList {
  #element;
  #valueSet;
  #attribute;
  #domain;

  constructor(initialValue, element, attribute, domain) {
    // Donor div is only used for its classList; never inserted anywhere.
    const hostingElement = document.createElement('div');
    this.domtokenlist = hostingElement.classList;

    this.#valueSet = false;
    this.domtokenlist.value = initialValue ?? '';
    this.#element = element;
    this.#attribute = attribute;
    this.#domain = domain;
  }

  get valueSet() {
    return this.#valueSet;
  }

  get length() {
    return this.domtokenlist.length;
  }

  get value() {
    return this.domtokenlist.value;
  }
  set value(val) {
    if (val === null) {
      this.domtokenlist.value = '';
    } else {
      this.domtokenlist.value = val.toLowerCase();
      this.#valueSet = true;
      this.#element.setAttribute(this.#attribute, this.domtokenlist.value);
      this.#valueSet = false;
    }
  }

  item(index) {
    return this.domtokenlist.item(index);
  }

  contains(token) {
    return this.domtokenlist.contains(token);
  }

  add(token) {
    this.domtokenlist.add(token);
    this.#element.setAttribute(this.#attribute, this.domtokenlist.value);
  }

  remove(token) {
    this.domtokenlist.remove(token);
    this.#element.setAttribute(this.#attribute, this.domtokenlist.value);
  }

  replace(oldToken, newToken) {
    this.domtokenlist.replace(oldToken, newToken);
    this.#element.setAttribute(this.#attribute, this.domtokenlist.value);
  }

  supports(token) {
    return this.#domain.includes(token);
  }

  toggle(token, force) {
    this.domtokenlist.toggle(token, force);
    this.#element.setAttribute(this.#attribute, this.domtokenlist.value);
  }

  entries() {
    return this.domtokenlist.entries();
  }

  forEach(callback, thisArg) {
    this.domtokenlist.forEach(callback, thisArg);
  }

  keys() {
    return this.domtokenlist.keys();
  }

  values() {
    return this.domtokenlist.values();
  }

  [Symbol.iterator]() {
    return this.domtokenlist.values();
  }

  toString() {
    return this.domtokenlist.value;
  }
}
