/**
 * Right-click / keyboard-activated context menu for `<mapml-viewer>`, ported
 * from MapML.js's `src/mapml/handlers/ContextMenu.js` to a framework-neutral
 * class (the same approach the MapML-MapLibre port takes in
 * `src/controls/ContextMenu.ts`). It is not an `ol/control/Control`: it mounts
 * a plain menu element into the viewer's shadow root and drives OpenLayers via
 * the viewer's public API, so its behaviour and DOM stay diffable against the
 * two sibling ports.
 *
 * MVP item set (order + shortcut hints from MapML.js): Back / Forward /
 * Reload / Fullscreen / Paste / Toggle Controls. Copy / Debug / View Source
 * arrive in later slices.
 *
 * Keyboard semantics mirror MapML.js:
 *   Map-wide (menu closed, viewer focused):
 *     - Alt+ArrowLeft  → back()
 *     - Alt+ArrowRight → forward()
 *     - Ctrl+R         → reload() (only when there is history to reset to;
 *                        otherwise the browser's own reload is left alone)
 *     - ContextMenu / Shift+F10 → open the menu at the viewport centre
 *   Menu-open:
 *     - ArrowUp / ArrowDown / Home / End → navigate
 *     - Enter / Space → activate focused item
 *     - F → toggle fullscreen
 *     - Escape / ContextMenu → close
 */
import { MapKeyboard } from './MapKeyboard.js';
import { Util } from '../utils/Util.js';

export class ContextMenu {
  constructor(viewer) {
    this._viewer = viewer;
    this._map = viewer.map;
    this._locale = viewer.locale;
    this._activeIndex = 0;
    this._wasOpenedByKeyboard = false;

    this._menu = document.createElement('div');
    this._menu.className = 'mapml-contextmenu';
    this._menu.setAttribute('role', 'menu');
    this._menu.setAttribute('tabindex', '-1');
    this._menu.hidden = true;
    // Mounted inside .mapml-container (position: relative) so pixel
    // coordinates from OpenLayers map events place it directly.
    viewer._container.appendChild(this._menu);

    this._buildItems();

    this._onMapContextMenu = this._onMapContextMenu.bind(this);
    this._onDocumentMouseDown = this._onDocumentMouseDown.bind(this);
    this._onDocumentKeyDown = this._onDocumentKeyDown.bind(this);
    this._onFullscreenChange = this._syncFullscreenLabel.bind(this);
    this._onMenuKeyDown = this._onMenuKeyDown.bind(this);

    this._map.on('contextmenu', this._onMapContextMenu);
    this._menu.addEventListener('keydown', this._onMenuKeyDown);
    document.addEventListener('mousedown', this._onDocumentMouseDown, true);
    document.addEventListener('keydown', this._onDocumentKeyDown);
    document.addEventListener('fullscreenchange', this._onFullscreenChange);

    this._updateEnabledState();
  }

  destroy() {
    this._map.un('contextmenu', this._onMapContextMenu);
    this._menu.removeEventListener('keydown', this._onMenuKeyDown);
    document.removeEventListener('mousedown', this._onDocumentMouseDown, true);
    document.removeEventListener('keydown', this._onDocumentKeyDown);
    document.removeEventListener('fullscreenchange', this._onFullscreenChange);
    this._menu.remove();
  }

  _buildItems() {
    const L = this._locale;
    // Order + shortcut hints match MapML.js's ContextMenu.js items 0–3.
    const defs = [
      {
        id: 'back',
        label: L.cmBack,
        kbd: 'Alt+Left Arrow',
        run: () => this._viewer.back(),
        isEnabled: () => this._historyState().canBack
      },
      {
        id: 'forward',
        label: L.cmForward,
        kbd: 'Alt+Right Arrow',
        run: () => this._viewer.forward(),
        isEnabled: () => this._historyState().canForward
      },
      {
        id: 'reload',
        label: L.cmReload,
        kbd: 'Ctrl+R',
        run: () => this._viewer.reload(),
        isEnabled: () => this._historyState().canReload
      },
      {
        id: 'fullscreen',
        label: L.btnFullScreen,
        kbd: 'F',
        run: () => this._viewer.toggleFullScreen()
      },
      { separator: true },
      {
        id: 'paste',
        label: L.cmPasteLayer,
        kbd: 'P',
        run: () => this._paste()
      },
      { separator: true },
      {
        id: 'toggle-controls',
        label: L.cmToggleControls,
        kbd: 'T',
        run: () => this._viewer.toggleControls()
      }
    ];

    this._items = [];
    for (const def of defs) {
      if (def.separator) {
        const sep = document.createElement('div');
        sep.className = 'mapml-contextmenu-separator';
        sep.setAttribute('role', 'separator');
        this._menu.appendChild(sep);
        continue;
      }
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'mapml-contextmenu-item';
      btn.setAttribute('role', 'menuitem');
      btn.dataset.id = def.id;
      btn.tabIndex = -1;
      btn.innerHTML = `<span>${def.label}</span><kbd>${def.kbd}</kbd>`;
      btn.addEventListener('click', () => {
        if (btn.disabled) return;
        def.run();
        this.close();
      });
      this._menu.appendChild(btn);
      this._items.push({
        el: btn,
        id: def.id,
        isEnabled: def.isEnabled ?? (() => true)
      });
    }
  }

  _historyState() {
    return (
      this._viewer._history?.getState() ?? {
        canBack: false,
        canForward: false,
        canReload: false
      }
    );
  }

  _updateEnabledState() {
    for (const item of this._items) {
      const enabled = item.isEnabled();
      item.el.disabled = !enabled;
      item.el.setAttribute('aria-disabled', enabled ? 'false' : 'true');
    }
    this._syncFullscreenLabel();
  }

  _syncFullscreenLabel() {
    const item = this._items?.find((it) => it.id === 'fullscreen');
    if (!item) return;
    const inFs = document.fullscreenElement === this._viewer;
    const label = inFs
      ? this._locale.btnExitFullScreen
      : this._locale.btnFullScreen;
    item.el.innerHTML = `<span>${label}</span><kbd>F</kbd>`;
  }

  // Read the clipboard and delegate to Util._pasteLayer, which appends a
  // <map-layer> to the viewer for pasted <map-layer>/<map-feature> markup, a
  // URL (as <map-layer src>), or GeoJSON. Ported from MapML.js ContextMenu._paste.
  _paste() {
    navigator.clipboard.readText().then((text) => {
      Util._pasteLayer(this._viewer, text);
    });
  }

  get isOpen() {
    return !this._menu.hidden;
  }

  _openAt(x, y, byKeyboard) {
    this._updateEnabledState();
    this._wasOpenedByKeyboard = byKeyboard;
    this._menu.hidden = false;
    // Suspend OpenLayers' arrow-key pan/zoom so navigation keys reach the menu
    // rather than moving the map (they act on any non-editable focus).
    this._suspendMapKeyboard();

    const size = this._map.getSize() ?? [0, 0];
    const maxX = Math.max(0, size[0] - this._menu.offsetWidth - 2);
    const maxY = Math.max(0, size[1] - this._menu.offsetHeight - 2);
    this._menu.style.left = `${Math.min(Math.max(0, x), maxX)}px`;
    this._menu.style.top = `${Math.min(Math.max(0, y), maxY)}px`;

    if (byKeyboard) {
      const first = this._firstEnabledIndex();
      if (first >= 0) this._focusItem(first);
      else this._menu.focus();
    }
  }

  close() {
    if (this._menu.hidden) return;
    this._menu.hidden = true;
    this._restoreMapKeyboard();
    if (this._wasOpenedByKeyboard) {
      this._viewer.focus?.();
    }
    this._wasOpenedByKeyboard = false;
  }

  _suspendMapKeyboard() {
    this._suspendedInteractions = [];
    this._map.getInteractions().forEach((interaction) => {
      if (interaction instanceof MapKeyboard && interaction.getActive()) {
        interaction.setActive(false);
        this._suspendedInteractions.push(interaction);
      }
    });
  }

  _restoreMapKeyboard() {
    this._suspendedInteractions?.forEach((interaction) =>
      interaction.setActive(true)
    );
    this._suspendedInteractions = [];
  }

  _onMapContextMenu(evt) {
    evt.originalEvent?.preventDefault();
    const [x, y] = evt.pixel;
    this._openAt(x, y, false);
  }

  _onDocumentMouseDown(e) {
    if (this._menu.hidden) return;
    if (e.composedPath().includes(this._menu)) return;
    this.close();
  }

  _onDocumentKeyDown(e) {
    const path = e.composedPath();
    if (!path.includes(this._viewer) && this._menu.hidden) return;

    if (!this._menu.hidden && e.key === 'Escape') {
      e.preventDefault();
      this.close();
      return;
    }
    if (
      !this._menu.hidden &&
      (e.key === 'ContextMenu' || (e.shiftKey && e.key === 'F10'))
    ) {
      e.preventDefault();
      this.close();
      return;
    }

    // Menu-open single-letter shortcut for a mouse-opened menu (focus
    // still on the canvas). When focus is inside the menu, _onMenuKeyDown
    // handles it first and preventDefault marks the event consumed.
    if (!this._menu.hidden && !e.defaultPrevented) {
      if (this._handleMenuLetterShortcut(e)) return;
    }

    if (this._menu.hidden) {
      this._handleMapWideShortcut(e);
    }
  }

  _handleMenuLetterShortcut(e) {
    if (this._menu.hidden) return false;
    if (e.ctrlKey || e.metaKey || e.altKey) return false;
    if (e.code === 'KeyF') {
      e.preventDefault();
      this._viewer.toggleFullScreen();
      this.close();
      return true;
    }
    if (e.code === 'KeyT') {
      e.preventDefault();
      this._viewer.toggleControls();
      this.close();
      return true;
    }
    if (e.code === 'KeyP') {
      e.preventDefault();
      this._paste();
      this.close();
      return true;
    }
    return false;
  }

  _handleMapWideShortcut(e) {
    if (
      this._menu.hidden &&
      (e.key === 'ContextMenu' || (e.shiftKey && e.key === 'F10'))
    ) {
      e.preventDefault();
      const size = this._map.getSize() ?? [0, 0];
      this._openAt(size[0] / 2, size[1] / 2, true);
      return;
    }
    if (e.altKey && !e.ctrlKey && !e.metaKey && !e.shiftKey) {
      if (e.code === 'ArrowLeft') {
        e.preventDefault();
        this._viewer.back();
        return;
      }
      if (e.code === 'ArrowRight') {
        e.preventDefault();
        this._viewer.forward();
        return;
      }
    }
    if (
      (e.ctrlKey || e.metaKey) &&
      e.code === 'KeyR' &&
      !e.altKey &&
      !e.shiftKey
    ) {
      // Only intercept the browser reload when there is map history to
      // reset to; at the initial location let the browser reload the page.
      if (this._historyState().canReload) {
        e.preventDefault();
        this._viewer.reload();
      }
    }
  }

  _onMenuKeyDown(e) {
    switch (e.code) {
      case 'Escape':
        e.preventDefault();
        this.close();
        return;
      case 'ArrowDown':
        e.preventDefault();
        this._moveFocus(1);
        return;
      case 'ArrowUp':
        e.preventDefault();
        this._moveFocus(-1);
        return;
      case 'Tab':
        e.preventDefault();
        this._moveFocus(e.shiftKey ? -1 : 1);
        return;
      case 'Home':
        e.preventDefault();
        this._focusItem(this._firstEnabledIndex());
        return;
      case 'End':
        e.preventDefault();
        this._focusItem(this._lastEnabledIndex());
        return;
      case 'Enter':
      case 'Space': {
        const active = this._items[this._activeIndex];
        if (active && !active.el.disabled) {
          e.preventDefault();
          active.el.click();
        }
        return;
      }
      case 'KeyF':
      case 'KeyT':
      case 'KeyP':
        this._handleMenuLetterShortcut(e);
        return;
    }
  }

  _moveFocus(delta) {
    const n = this._items.length;
    if (n === 0) return;
    let i = this._activeIndex;
    for (let step = 0; step < n; step++) {
      i = (i + delta + n) % n;
      if (!this._items[i].el.disabled) {
        this._focusItem(i);
        return;
      }
    }
  }

  _firstEnabledIndex() {
    return this._items.findIndex((it) => !it.el.disabled);
  }

  _lastEnabledIndex() {
    for (let i = this._items.length - 1; i >= 0; i--) {
      if (!this._items[i].el.disabled) return i;
    }
    return -1;
  }

  _focusItem(i) {
    if (i < 0) return;
    for (let j = 0; j < this._items.length; j++) {
      this._items[j].el.tabIndex = j === i ? 0 : -1;
    }
    this._activeIndex = i;
    this._items[i].el.focus();
  }
}
