/**
 * `<mapml-viewer>` — root MapML map container.
 *
 * Phase 1: creates a native OpenLayers `Map` + `View` in the projection named
 * by the `projection` attribute, using the resolutions/extent derived from the
 * `M[projection]` tables (see mapml/geo/crs/olcrs.js). Method names mirror
 * MapML.js's viewer (`_initShadowRoot`, `_createMap`) to keep the two ports
 * diffable; the Leaflet `L.map(...)` call becomes an `ol/Map` + `View`.
 *
 * Controls, history, layer wiring and map-caption/locale handling are ported
 * in later phases.
 */
import Map from 'ol/Map.js';
import View from 'ol/View.js';
import Zoom from 'ol/control/Zoom.js';
import { defaults as defaultInteractions } from 'ol/interaction/defaults.js';
import { transform } from 'ol/proj.js';
import olCss from 'ol/ol.css?inline';

import './mapml/GlobalM.js';
import { getProjection } from './mapml/geo/crs/olcrs.js';
import { LayerControl } from './mapml/control/LayerControl.js';
import { layerControlCss } from './mapml/control/layerControl.css.js';
import { AttributionControl } from './mapml/control/AttributionControl.js';
import { attributionControlCss } from './mapml/control/attributionControl.css.js';
import { ReloadButton } from './mapml/control/ReloadButton.js';
import { reloadButtonCss } from './mapml/control/reloadButton.css.js';
import { FullscreenButton } from './mapml/control/FullscreenButton.js';
import { fullscreenButtonCss } from './mapml/control/fullscreenButton.css.js';
import { zoomControlCss } from './mapml/control/zoomControl.css.js';
import { MapHistory } from './mapml/handlers/MapHistory.js';
import { MapKeyboard } from './mapml/handlers/MapKeyboard.js';
import { ContextMenu } from './mapml/handlers/ContextMenu.js';
import { contextMenuCss } from './mapml/handlers/contextMenu.css.js';
import { FeatureInteraction } from './mapml/handlers/FeatureInteraction.js';
import { FeatureIndex } from './mapml/handlers/FeatureIndex.js';
import { QueryHandler } from './mapml/handlers/QueryHandler.js';
import { featureInteractionCss } from './mapml/handlers/featureInteraction.css.js';
import {
  FeatureIndexOverlay,
  featureIndexPreference
} from './mapml/layers/FeatureIndexOverlay.js';
import { featureIndexOverlayCss } from './mapml/layers/featureIndexOverlay.css.js';
import { FeatureIndexControl } from './mapml/control/FeatureIndexControl.js';
import { featureIndexControlCss } from './mapml/control/featureIndexControl.css.js';
import { SearchButton } from './mapml/control/SearchButton.js';
import { searchControlCss } from './mapml/control/searchControl.css.js';
import { DOMTokenList } from './mapml/utils/DOMTokenList.js';

const DEFAULT_PROJECTION = 'OSMTILE';

// Logical tab order of the map's controls, matching Leaflet/MapML.js, whose
// control-position corners sit in the DOM as top-left, top-right, bottom-left,
// bottom-right. OpenLayers instead renders every control into one container in
// add-order, so `_orderControls()` restores this spatial order. The full tab
// order is: viewer host (focus ring) -> features (one stop, arrow-navigated)
// -> these corners in order.
//
// Preserve this as controls are added: tag each control element with
// `dataset.mapmlCorner` (which corner) and `dataset.mapmlOrder` (rank within
// the corner; lower is earlier). Each corner has a fixed ANCHOR control
// (mapmlOrder 0) that must always lead it, so screen-reader users hear a stable
// first control per corner regardless of install order:
//   top-left    : Zoom (then Reload, Fullscreen)
//   top-right   : Layer control
//   bottom-left : Scale bar
//   bottom-right: Attribution
const CONTROL_CORNER_ORDER = [
  'top-left',
  'top-right',
  'bottom-left',
  'bottom-right'
];

export class HTMLMapmlViewerElement extends HTMLElement {
  static get observedAttributes() {
    return [
      'lat',
      'lon',
      'zoom',
      'projection',
      'width',
      'height',
      'controls',
      'controlslist',
      'featureindex'
    ];
  }

  constructor() {
    super();
    // Resolved once _createMap() has run, so children (which upgrade before
    // the parent's connectedCallback) can await the map before adding layers.
    this._ready = new Promise((resolve) => {
      this._resolveReady = resolve;
    });
  }

  get map() {
    return this._map;
  }

  // UI strings for the viewer chrome (layer control, context menu, etc.),
  // resolved from the element's `:lang()` by _setLocale(). Falls back to the
  // browser-picked default before connection.
  get locale() {
    return this._locale || window.M.options.locale;
  }

  _setLocale() {
    if (this.closest(':lang(fr)') === this) {
      this._locale = window.M.options.localeFr;
    } else if (this.closest(':lang(en)') === this) {
      this._locale = window.M.options.localeEn;
    } else {
      // "browser" locale
      this._locale = window.M.options.locale;
    }
  }

  // The direct-child <map-layer> elements, in DOM order.
  get layers() {
    return Array.from(this.querySelectorAll(':scope > map-layer'));
  }

  whenReady() {
    return this._ready;
  }

  get projection() {
    return this.getAttribute('projection') || DEFAULT_PROJECTION;
  }
  get lat() {
    return +(this.getAttribute('lat') || 0);
  }
  get lon() {
    return +(this.getAttribute('lon') || 0);
  }
  get zoom() {
    return +(this.getAttribute('zoom') || 0);
  }

  // Width/height mirror the `<img>`-style presentation attributes (ported from
  // MapML.js mapml-viewer.js): the getter reads the computed pixel size, the
  // setter reflects to the attribute (which resizes via attributeChangedCallback).
  get width() {
    return parseInt(window.getComputedStyle(this).width, 10);
  }
  set width(val) {
    this.setAttribute('width', val);
  }
  get height() {
    return parseInt(window.getComputedStyle(this).height, 10);
  }
  set height(val) {
    this.setAttribute('height', val);
  }

  connectedCallback() {
    if (this._map) {
      return;
    }
    // Focusable so keyboard shortcuts (context menu, history) reach the viewer.
    if (!this.hasAttribute('tabindex')) {
      this.setAttribute('tabindex', '0');
    }
    // Expose the map as an ARIA application (mirrors MapML.js); its accessible
    // name comes from <map-caption> via map-caption.js.
    this.setAttribute('role', 'application');
    this._setLocale();
    this._initShadowRoot();
    this._createMap();
    // Apply the `<img>`-style width/height attributes over the default object
    // size (ported from MapML.js mapml-viewer.js connectedCallback).
    if (this.hasAttribute('width')) {
      this._changeWidth(this.getAttribute('width'));
    }
    if (this.hasAttribute('height')) {
      this._changeHeight(this.getAttribute('height'));
    }
    this._resolveReady(this._map);
  }

  disconnectedCallback() {
    if (this._map) {
      document.removeEventListener(
        'fullscreenchange',
        this._onFullscreenChange
      );
      this._contextMenu?.destroy();
      this._contextMenu = null;
      if (this._featureIndexControl) {
        this._map.removeControl(this._featureIndexControl);
        this._featureIndexControl.destroy();
        this._featureIndexControl = null;
      }
      if (this._searchButton) {
        this._map.removeControl(this._searchButton);
        this._searchButton.destroy();
        this._searchButton = null;
      }
      this._featureIndexOverlay?.destroy();
      this._featureIndexOverlay = null;
      this._featureIndex?.destroy();
      this._featureIndex = null;
      this._featureInteraction?.destroy();
      this._featureInteraction = null;
      this._queryHandler?.destroy();
      this._queryHandler = null;
      this._history?.disable();
      this._history = null;
      this._map.setTarget(null);
      this._map = null;
    }
  }

  _initShadowRoot() {
    const shadow = this.shadowRoot || this.attachShadow({ mode: 'open' });
    const style = document.createElement('style');
    style.textContent = [
      olCss,
      layerControlCss,
      attributionControlCss,
      zoomControlCss,
      reloadButtonCss,
      fullscreenButtonCss,
      contextMenuCss,
      featureInteractionCss,
      featureIndexOverlayCss,
      featureIndexControlCss,
      searchControlCss,
      // Global hidden rule (ported from MapML.js mapml.css): `!important` beats
      // author `display` rules like `.mapml-layer-item-settings > *`, which
      // otherwise reveal an empty [hidden] sublayers fieldset.
      '[hidden] { display: none !important; }',
      // Single source of truth for the focus-ring colour, inherited by every
      // control and the feature ring in this shadow root. Owned (not the UA's
      // -webkit-focus-ring-color) so it's consistent cross-platform and needs no
      // vendor prefix; forced-colors mode swaps to a system colour.
      ':host { --mapml-focus-ring-color: #e59700; }',
      '@media (forced-colors: active) { :host { --mapml-focus-ring-color: Highlight; } }',
      // Frame the whole map whenever focus is anywhere inside the viewer (the
      // map surface, a feature proxy, or a control). Unlike :host(:focus-visible),
      // :focus-within fires when focus lands on an inner element (the normal case
      // once features or controls exist), so the map's focus is actually visible.
      // The ring is a ::after overlay on OpenLayers' top-most map child so it
      // paints above the tile canvas (an inset outline on .mapml-container hides
      // beneath the canvas), inset via outline-offset so no size containment is
      // needed to clip it.
      ':host(:focus) { outline: none; }',
      ':host(:focus-within) .ol-viewport::after { content: ""; position: absolute; inset: 0; pointer-events: none; outline: 2px solid var(--mapml-focus-ring-color); outline-offset: -3px; }',
      '.mapml-container { position: relative; width: 100%; height: 100%; }'
    ].join('\n');
    // Default object size + size containment (ported from MapML.js
    // mapml-viewer.js host CSS), kept as its own stylesheet whose single rule is
    // mutated by _changeWidth/_changeHeight (the analog of MapML.js poking
    // styleSheets[0].cssRules[0]). `contain: layout size` decouples the host's
    // size from its contents and the 300x150 default gives it a definite box, so
    // the map is never a 0-height container and author `min-height`/percentage
    // children (.mapml-container) resolve. Author page CSS and the width/height
    // attributes override this default.
    const sizeStyle = document.createElement('style');
    sizeStyle.textContent =
      ':host { display: inline-block; contain: layout size; width: 300px; height: 150px; }';
    this._sizeStyle = sizeStyle;
    const container = document.createElement('div');
    container.className = 'mapml-container';
    shadow.append(sizeStyle, style, container);
    this._container = container;
  }

  _createMap() {
    if (this._map) {
      return;
    }
    const mProj = window.M[this.projection];
    const projection = getProjection(mProj);
    // View center is in the view projection's units; attributes are lon/lat.
    const center = transform(
      [this.lon, this.lat],
      'EPSG:4326',
      projection.getCode()
    );
    this._view = new View({
      projection,
      center,
      zoom: this.zoom,
      resolutions: mProj.options.resolutions
    });
    this._attributionControl = new AttributionControl({ viewer: this });
    this._attributionControl.element.dataset.mapmlCorner = 'bottom-right';
    this._attributionControl.element.dataset.mapmlOrder = '0';
    this._map = new Map({
      target: this._container,
      view: this._view,
      // Attribution is always present (mirrors MapML.js); tile sources feed it
      // via <map-link rel="license"> extracted in map-link. The circular
      // info-outline disclosure widget starts collapsed.
      controls: [this._attributionControl],
      // Replace OpenLayers' split KeyboardPan/KeyboardZoom with a single
      // MapML.js-style handler (Shift/Ctrl+Arrow pan modifiers, whole-level
      // +/- zoom).
      interactions: defaultInteractions({ keyboard: false }).extend([
        new MapKeyboard()
      ]),
      layers: []
    });
    // OpenLayers, unlike Leaflet, doesn't move DOM focus into the map when the
    // user drags/clicks the map surface, so keyboard features that need map
    // focus (MapKeyboard pan/zoom, the feature-index number keys) go dead after
    // a mouse pan. Mirror Leaflet: focus the viewport on pointerdown on the map
    // surface, but let clicks on a control focus their own button.
    const viewport = this._map.getViewport();
    if (!viewport.hasAttribute('tabindex')) {
      viewport.setAttribute('tabindex', '-1');
    }
    viewport.addEventListener('pointerdown', (e) => {
      if (e.target.closest('.ol-control')) return;
      viewport.focus({ preventScroll: true });
    });
    // Optional controls are gated on the `controls` attribute (mirrors
    // MapML.js). Attribution is sacred and lives outside this path so authors
    // cannot suppress the data-licensing UI.
    if (this.controls) {
      this._installControls();
    }
    this._history = new MapHistory(this._map);
    this._history.enable();
    this._contextMenu = new ContextMenu(this);
    this._featureInteraction = new FeatureInteraction(this);
    this._queryHandler = new QueryHandler(this);
    this._queryHandler.enable();
    this._featureIndex = new FeatureIndex(this);
    this._featureIndexOverlay = new FeatureIndexOverlay(this);
    // controlslist DOMTokenList (mirrors MapML.js); `featureindex` is the token
    // that installs the feature-index overlay control. The other tokens are
    // kept in the domain for forward-compat as their controls land.
    this._controlsList = new DOMTokenList(
      this.getAttribute('controlslist'),
      this,
      'controlslist',
      [
        'noreload',
        'nofullscreen',
        'nozoom',
        'nolayer',
        'noscale',
        'geolocation',
        'search',
        'static',
        'featureindex'
      ]
    );
    // Resolve the overlay's initial state first so the control (created by
    // _applyControlsList) renders the correct aria-pressed on construction.
    this._initFeatureIndexState();
    this._applyControlsList();
    // Keep the map sized to its container when entering/leaving fullscreen.
    this._onFullscreenChange = () => this._map?.updateSize();
    document.addEventListener('fullscreenchange', this._onFullscreenChange);
  }

  // Navigation history API (mirrors MapML.js's viewer back/forward/reload).
  back() {
    this._history?.back();
  }

  forward() {
    this._history?.forward();
  }

  reload() {
    this._history?.reload();
  }

  // Resize the host (and OL viewport) to an author-supplied pixel width/height,
  // overriding the default object size. Ported from MapML.js mapml-viewer.js
  // _changeWidth/_changeHeight (which poke the :host rule + container, then
  // invalidateSize); OL's equivalent of Leaflet invalidateSize is updateSize.
  _changeWidth(width) {
    if (this._sizeStyle?.sheet) {
      this._sizeStyle.sheet.cssRules[0].style.width = width + 'px';
    }
    if (this._container) {
      this._container.style.width = width + 'px';
    }
    this._map?.updateSize();
  }

  _changeHeight(height) {
    if (this._sizeStyle?.sheet) {
      this._sizeStyle.sheet.cssRules[0].style.height = height + 'px';
    }
    if (this._container) {
      this._container.style.height = height + 'px';
    }
    this._map?.updateSize();
  }

  // Whether the optional controls (currently the layer control) are shown.
  // Presence of the `controls` attribute gates them, mirroring MapML.js.
  get controls() {
    return this.hasAttribute('controls');
  }
  set controls(value) {
    if (value) {
      this.setAttribute('controls', '');
    } else {
      this.removeAttribute('controls');
    }
  }

  // Flip control visibility. Mirrors MapML.js's _toggleControls (which flips
  // mapEl.controls); the attribute observer installs/uninstalls the controls.
  toggleControls() {
    this.controls = !this.controls;
  }

  // The controlslist DOMTokenList (mirrors MapML.js's `controlsList` property).
  get controlsList() {
    return this._controlsList;
  }
  set controlsList(value) {
    this._controlsList.value = value;
    this.setAttribute('controlslist', value);
  }

  // Whether the feature-index accessibility overlay (reticle + aria-live list)
  // is active. A user/UA preference (M.options.featureIndexOverlayOption) wins
  // over this setter, so it can't be toggled from the map UI when forced.
  get featureIndex() {
    return Boolean(this._featureIndexActive);
  }
  set featureIndex(value) {
    if (featureIndexPreference() !== undefined) return;
    const on = Boolean(value);
    this._featureIndexActive = on;
    if (on) this._featureIndexOverlay?.enable();
    else this._featureIndexOverlay?.disable();
    // Reflect to the attribute only when it is already present, so a control
    // toggle doesn't churn author markup (matches MapML-MapLibre).
    if (!on && this.hasAttribute('featureindex')) {
      this.removeAttribute('featureindex');
    }
    this.dispatchEvent(new CustomEvent('mapml:featureindexchanged'));
  }

  // Install/uninstall optional controls named by the controlslist tokens.
  // The `featureindex` token opts a control IN; the `no*` tokens opt the
  // standard controls (zoom/reload/fullscreen/layer) OUT — reconciled here.
  _applyControlsList() {
    if (!this._controlsList || !this._map) return;
    const wantIndex = this._controlsList.contains('featureindex');
    if (wantIndex && !this._featureIndexControl) {
      this._featureIndexControl = new FeatureIndexControl(this);
      this._map.addControl(this._featureIndexControl);
      this._featureIndexControl.element.dataset.mapmlCorner = 'top-right';
      this._featureIndexControl.element.dataset.mapmlOrder = '10';
      this._orderControls();
    } else if (!wantIndex && this._featureIndexControl) {
      this._map.removeControl(this._featureIndexControl);
      this._featureIndexControl.destroy();
      this._featureIndexControl = null;
    }
    // `search` opts in a top-left magnifier; the control self-manages its
    // enabled state from checked layers advertising map-link[rel=search].
    const wantSearch = this._controlsList.contains('search');
    if (wantSearch && !this._searchButton) {
      this._searchButton = new SearchButton(this);
      this._map.addControl(this._searchButton);
      this._searchButton.element.dataset.mapmlCorner = 'top-left';
      this._searchButton.element.dataset.mapmlOrder = '1';
      this._searchButton.element.dataset.mapmlStackHeight = '40';
      this._orderControls();
    } else if (!wantSearch && this._searchButton) {
      this._map.removeControl(this._searchButton);
      this._searchButton.destroy();
      this._searchButton = null;
    }
    this._reconcileStandardControls();
  }

  // Apply the initial feature-index overlay state: a user/UA preference forces
  // it on/off, otherwise the `featureindex` boolean attribute opts in.
  _initFeatureIndexState() {
    const pref = featureIndexPreference();
    const on = pref === 'on' || (pref === undefined && this.hasAttribute('featureindex'));
    this._featureIndexActive = on;
    if (on) this._featureIndexOverlay?.enable();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (!this._map) {
      return;
    }
    switch (name) {
      case 'controls':
        if (oldValue === null && newValue !== null) {
          this._installControls();
        } else if (oldValue !== null && newValue === null) {
          this._uninstallControls();
        }
        break;
      case 'width':
        if (oldValue !== newValue) {
          this._changeWidth(newValue);
        }
        break;
      case 'height':
        if (oldValue !== newValue) {
          this._changeHeight(newValue);
        }
        break;
      case 'controlslist':
        if (this._controlsList && this._controlsList.valueSet === false) {
          this._controlsList.value = newValue;
        }
        this._applyControlsList();
        break;
      case 'featureindex': {
        // Author toggled the boolean attribute; a forced preference wins.
        if (featureIndexPreference() !== undefined) break;
        const present = newValue !== null;
        if (present && !this._featureIndexActive) {
          this._featureIndexActive = true;
          this._featureIndexOverlay?.enable();
          this.dispatchEvent(new CustomEvent('mapml:featureindexchanged'));
        } else if (!present && this._featureIndexActive) {
          this._featureIndexActive = false;
          this._featureIndexOverlay?.disable();
          this.dispatchEvent(new CustomEvent('mapml:featureindexchanged'));
        }
        break;
      }
    }
  }

  // Install/uninstall the optional controls. Attribution is untouched.
  _installControls() {
    this._reconcileStandardControls();
  }

  // The standard controls gated on the `controls` attribute and pruned by the
  // controlslist `no*` tokens. Ported from MapML.js's _createControls order
  // (zoom → reload → fullscreen top-left; layer control top-right).
  _standardControlsSpec() {
    return [
      {
        key: '_zoomControl',
        token: 'nozoom',
        corner: 'top-left',
        order: '0',
        stackHeight: 80,
        make: () =>
          new Zoom({
            zoomInTipLabel: this.locale.btnZoomIn,
            zoomOutTipLabel: this.locale.btnZoomOut,
            zoomInLabel: '+',
            zoomOutLabel: '\u2212'
          })
      },
      {
        key: '_reloadButton',
        token: 'noreload',
        corner: 'top-left',
        order: '2',
        stackHeight: 40,
        make: () => new ReloadButton(this)
      },
      {
        key: '_fullscreenButton',
        token: 'nofullscreen',
        corner: 'top-left',
        order: '3',
        stackHeight: 40,
        make: () => new FullscreenButton(this)
      },
      {
        key: '_layerControl',
        token: 'nolayer',
        corner: 'top-right',
        order: '0',
        make: () => new LayerControl(this)
      }
    ];
  }

  // Reconcile the standard controls against the `controls` attribute and the
  // controlslist tokens: create the ones that should be shown, remove the ones
  // that shouldn't. Called on install, on `controls` toggle and on a
  // controlslist change. Mirrors MapML.js's _showControls/_hideControls, which
  // toggle the same set based on the attribute and `no*` tokens.
  _reconcileStandardControls() {
    if (!this._map) return;
    const enabled = this.controls;
    for (const spec of this._standardControlsSpec()) {
      const suppressed = this._controlsList?.contains(spec.token) ?? false;
      const want = enabled && !suppressed;
      const have = Boolean(this[spec.key]);
      if (want && !have) {
        const ctrl = spec.make();
        this._map.addControl(ctrl);
        ctrl.element.dataset.mapmlCorner = spec.corner;
        ctrl.element.dataset.mapmlOrder = spec.order;
        if (spec.stackHeight) {
          ctrl.element.dataset.mapmlStackHeight = String(spec.stackHeight);
        }
        this[spec.key] = ctrl;
      } else if (!want && have) {
        this._removeStandardControl(spec.key);
      }
    }
    this._orderControls();
  }

  _removeStandardControl(key) {
    const ctrl = this[key];
    if (!ctrl) return;
    this._map.removeControl(ctrl);
    ctrl.destroy?.();
    this[key] = null;
  }

  // Reorder the control elements in OpenLayers' single control container to the
  // logical corner tab order (CONTROL_CORNER_ORDER), then by each corner's
  // fixed anchor rank (dataset.mapmlOrder). Controls are absolutely positioned,
  // so moving them in the DOM changes only tab order, not layout.
  _orderControls() {
    const stopEvent = this._map
      ?.getViewport()
      .querySelector('.ol-overlaycontainer-stopevent');
    if (!stopEvent) return;
    const corner = (el) => {
      const i = CONTROL_CORNER_ORDER.indexOf(el.dataset.mapmlCorner);
      return i === -1 ? CONTROL_CORNER_ORDER.length : i;
    };
    const order = (el) => Number(el.dataset.mapmlOrder) || 0;
    [...stopEvent.querySelectorAll(':scope > [data-mapml-corner]')]
      .sort((a, b) => corner(a) - corner(b) || order(a) - order(b))
      .forEach((el) => stopEvent.appendChild(el));
    this._layoutTopLeftColumn(stopEvent);
  }

  // Stack the top-left controls (zoom/search/reload/fullscreen, in mapmlOrder)
  // as a single column by assigning each an accumulated `top`. Unlike fixed CSS
  // offsets, this collapses the gap left by any excluded control (nozoom /
  // noreload / nofullscreen) so the remaining controls — and the opt-in search
  // button between zoom and reload — keep their relative places. Heights are the
  // controls' nominal stack heights (zoom bar 80px, single buttons 40px) with an
  // 8px gap between them.
  _layoutTopLeftColumn(stopEvent) {
    const gap = 8;
    let offset = 0;
    [...stopEvent.querySelectorAll(':scope > [data-mapml-corner="top-left"]')]
      .sort(
        (a, b) =>
          (Number(a.dataset.mapmlOrder) || 0) -
          (Number(b.dataset.mapmlOrder) || 0)
      )
      .forEach((el) => {
        el.style.top = `calc(.5em + ${offset}px)`;
        const height = Number(el.dataset.mapmlStackHeight) || el.offsetHeight || 40;
        offset += height + gap;
      });
  }
  _uninstallControls() {
    for (const spec of this._standardControlsSpec()) {
      this._removeStandardControl(spec.key);
    }
  }

  // Fullscreen the whole viewer. MapML.js exposes this via Leaflet's
  // fullscreen plugin (`map.toggleFullscreen()`); OpenLayers ships no such
  // helper, so drive the standard Fullscreen API on the host element. The
  // top-left FullscreenButton and the context menu / keyboard all route here.
  toggleFullScreen() {
    if (document.fullscreenElement === this) {
      document.exitFullscreen?.();
    } else {
      this.requestFullscreen?.();
    }
  }
}

if (!customElements.get('mapml-viewer')) {
  customElements.define('mapml-viewer', HTMLMapmlViewerElement);
}
