/**
 * Stylesheet for the {@link FeatureIndexOverlay} — the centred reticle box and
 * the `aria-live` `<output>` listing the features overlapping it. Ported 1:1
 * from MapML.js's src/mapml.css ("Feature Index" section) so the overlay looks
 * identical across renderers. Positions are relative to the OL viewport the
 * overlay appends its box + `<output>` into. Injected into the viewer's shadow
 * styles alongside the other control stylesheets.
 */
export const featureIndexOverlayCss = /* css */ `
.mapml-feature-index-box {
  margin: -8% 0 0 -8%;
  width: 16%;
  left: 50%;
  top: 50%;
  position: absolute;
  z-index: 10000;
  outline: 2px solid #fff;
  pointer-events: none;
}

.mapml-feature-index-box:after {
  display: block;
  content: '';
  padding-top: 100%;
}

.mapml-feature-index-box > svg {
  position: absolute;
  width: 100%;
  height: 100%;
}

.mapml-feature-index {
  outline: 1px solid #000000;
  contain: content;
  border-radius: 4px;
  background-color: #fff;
  cursor: default;
  z-index: 1000;
  position: absolute;
  top: auto;
  left: 50%;
  transform: translateX(-50%);
  bottom: 30px;
  padding-top: 5px;
  height: 92px;
  width: 450px;
  font-size: 16px;
  /* Leaflet's default UI font, normally inherited from .leaflet-container via
     leaflet.css (which we don't ship in the OL port). */
  font-family: 'Helvetica Neue', Arial, Helvetica, sans-serif;
}

/* Size the results menu to the map's width, mirroring MapML.js's container
   queries. MapML.js declares the container on .leaflet-container
   (container: leafletmap / size); here it lives on .mapml-container. inline-size
   is enough — MapML.js only uses the block axis for a scale-bar query we don't
   ship. Below 650px the menu tracks the viewport width; below 390px it also
   lifts clear of the centred reticle. */
.mapml-container {
  container-type: inline-size;
  container-name: mapmlviewer;
}

@container mapmlviewer (max-width: 650px) {
  .mapml-feature-index {
    width: 70cqw;
  }
}

@container mapmlviewer (max-width: 390px) {
  .mapml-feature-index {
    bottom: 100px;
  }
}

.mapml-feature-index-content > span {
  width: 140px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  display: inline-block;
  padding-left: 5px;
  padding-right: 5px;
}

.mapml-feature-index-content > span > kbd {
  background-color: lightgrey;
  padding-right: 4px;
  padding-left: 4px;
  border-radius: 4px;
}

/* The trailing ", " node is a screen-reader-only auditory pause. */
.mapml-feature-index-content > span > span {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

/* Hides the aria-live output from sighted users while keeping it in the
 * accessibility tree (screen readers still announce its contents). */
.mapml-feature-index.mapml-screen-reader-output {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}
`;
